namespace AquaFlow.Model.Responses;

public class NotificationResponse : AuditableResponse
{
    public string Title { get; set; } = string.Empty;
    public string Body { get; set; } = string.Empty;
    public string Type { get; set; } = string.Empty;
    public string Audience { get; set; } = string.Empty;
    public int CreatedById { get; set; }

    // True for notifications generated by a business event (SystemNotificationService), false
    // for admin news/announcements authored through /Notifications.
    public bool IsSystem { get; set; }

    // The record a system notification is about (a RelatedEntityTypes value + its id), used by
    // the clients for the deep link. Both null for admin notifications.
    public string? RelatedEntityType { get; set; }
    public int? RelatedEntityId { get; set; }
}
